/* =========================================================
   NEXIFY — Design System v1.0
   Brand colors: #3268ac (blue) · #f26339 (deep orange) · #f89241 (light orange)
   ========================================================= */

:root {
  --c-blue: #3268ac;
  --c-blue-dark: #234e85;
  --c-blue-light: #5a8dcf;
  --c-blue-50: #eaf1fa;
  --c-orange: #f26339;
  --c-orange-dark: #d44a22;
  --c-orange-light: #f89241;
  --c-orange-50: #fff2ec;
  --c-ink: #0f1623;
  --c-ink-2: #1f2a3d;
  --c-text: #2b3850;
  --c-muted: #6b7280;
  --c-line: #e5e7eb;
  --c-line-2: #d1d5db;
  --c-bg: #ffffff;
  --c-bg-soft: #f8fafc;
  --c-bg-card: #ffffff;
  --radius: 14px;
  --radius-lg: 22px;
  --shadow-sm: 0 1px 3px rgba(15,22,35,.06), 0 1px 2px rgba(15,22,35,.04);
  --shadow: 0 10px 30px -12px rgba(50,104,172,.18), 0 4px 12px -4px rgba(15,22,35,.06);
  --shadow-lg: 0 30px 60px -20px rgba(50,104,172,.28), 0 18px 40px -12px rgba(242,99,57,.15);
  --shadow-orange: 0 20px 40px -12px rgba(242,99,57,.45);
  --gradient-brand: linear-gradient(135deg, var(--c-orange) 0%, var(--c-orange-light) 100%);
  --gradient-blue: linear-gradient(135deg, var(--c-blue) 0%, var(--c-blue-light) 100%);
  --font-sans: 'Inter', system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --font-display: 'Poppins', 'Inter', sans-serif;
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; overflow-x: hidden; }
body { margin: 0; font-family: var(--font-sans); font-size: 16px; line-height: 1.6; color: var(--c-text); background: var(--c-bg); -webkit-font-smoothing: antialiased; overflow-x: hidden; }
img, svg { max-width: 100%; display: block; }
a { color: var(--c-blue); text-decoration: none; transition: color .2s; }
a:hover { color: var(--c-orange); }
h1, h2, h3, h4 { font-family: var(--font-display); color: var(--c-ink); margin: 0 0 .5em; line-height: 1.2; letter-spacing: -.01em; }
h1 { font-size: clamp(2rem, 5vw, 3.4rem); font-weight: 800; line-height: 1.1; }
h2 { font-size: clamp(1.6rem, 3.5vw, 2.4rem); font-weight: 700; }
h3 { font-size: clamp(1.2rem, 2.2vw, 1.4rem); font-weight: 700; }
h4 { font-size: 1.1rem; font-weight: 600; }
p { margin: 0 0 1rem; }
.lead { font-size: 1.15rem; color: var(--c-text); }
.container { width: min(1180px, 92%); margin: 0 auto; }
.container-narrow { width: min(820px, 92%); margin: 0 auto; }
.section { padding: 80px 0; }
.section-sm { padding: 50px 0; }
.section-lg { padding: 110px 0; }
.section-soft { background: var(--c-bg-soft); }
.section-blue { background: linear-gradient(135deg, var(--c-blue) 0%, var(--c-blue-dark) 100%); color: #fff; }
.section-blue h1, .section-blue h2, .section-blue h3 { color: #fff; }
.section-blue p { color: rgba(255,255,255,.88); }
.grid { display: grid; gap: 24px; }
.grid-2 { grid-template-columns: repeat(2, 1fr); }
.grid-3 { grid-template-columns: repeat(3, 1fr); }
.grid-4 { grid-template-columns: repeat(4, 1fr); }
@media (max-width: 880px) { .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; } }
@media (max-width: 1080px) { .grid-4 { grid-template-columns: repeat(2, 1fr); } }
.eyebrow { display: inline-block; font-size: .8rem; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--c-orange); margin-bottom: 14px; }
.section-blue .eyebrow { color: var(--c-orange-light); }
.text-center { text-align: center; }
.mt-2 { margin-top: 1rem; } .mt-3 { margin-top: 1.5rem; } .mt-4 { margin-top: 2rem; }

.btn { display: inline-flex; align-items: center; gap: 10px; padding: 14px 26px; border-radius: 999px; font-weight: 700; font-size: 1rem; border: 2px solid transparent; cursor: pointer; transition: transform .15s, box-shadow .25s, background .2s, color .2s, border-color .2s; font-family: inherit; text-align: center; white-space: nowrap; }
.btn-primary { background: var(--gradient-brand); color: #fff; box-shadow: var(--shadow-orange); }
.btn-primary:hover { transform: translateY(-2px); box-shadow: 0 26px 48px -12px rgba(242,99,57,.55); color: #fff; }
.btn-outline { background: transparent; color: var(--c-blue); border-color: var(--c-blue); }
.btn-outline:hover { background: var(--c-blue); color: #fff; }
.btn-ghost { background: rgba(255,255,255,.1); color: #fff; border-color: rgba(255,255,255,.3); }
.btn-ghost:hover { background: rgba(255,255,255,.2); color: #fff; }
.btn-sm { padding: 10px 18px; font-size: .9rem; }
.btn-lg { padding: 18px 34px; font-size: 1.05rem; }
.btn-block { display: flex; width: 100%; justify-content: center; }
.btn-row { display: flex; gap: 14px; flex-wrap: wrap; }
.btn-row.center { justify-content: center; }

/* backdrop-filter is on ::before so the header itself does NOT become a
   fixed-positioning containing block — which would trap the mobile nav
   behind page sections (known browser behaviour with backdrop-filter). */
.site-header { position: sticky; top: 0; z-index: 100; background: rgba(255,255,255,.92); border-bottom: 1px solid var(--c-line); }
.site-header::before { content: ''; position: absolute; inset: 0; backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px); z-index: -1; pointer-events: none; }
.nav-inner { display: flex; align-items: center; justify-content: space-between; padding: 14px 0; gap: 24px; }
.brand { display: flex; align-items: center; gap: 10px; }
.brand img { height: 76px; width: auto; }
@media (max-width: 600px) { .brand img { height: 52px; } }
.main-nav { display: flex; align-items: center; gap: 28px; }
.main-nav a { font-size: .95rem; font-weight: 500; color: var(--c-ink-2); position: relative; }
.main-nav a:hover { color: var(--c-orange); }
.main-nav a.active { color: var(--c-orange); }
.main-nav a.active::after { content: ''; position: absolute; left: 0; right: 0; bottom: -6px; height: 2px; background: var(--c-orange); border-radius: 2px; }
.nav-cta { padding: 10px 20px; }
.menu-toggle { display: none; width: 42px; height: 42px; border-radius: 10px; background: var(--c-blue-50); border: none; cursor: pointer; align-items: center; justify-content: center; }
.menu-toggle span { display: block; width: 20px; height: 2px; background: var(--c-blue); position: relative; }
.menu-toggle span::before, .menu-toggle span::after { content: ''; position: absolute; left: 0; right: 0; height: 2px; background: var(--c-blue); }
.menu-toggle span::before { top: -6px; }
.menu-toggle span::after { top: 6px; }
