cd /tmp && python3 << 'EOF'
from playwright.sync_api import sync_playwright

with sync_playwright() as p:
    browser = p.chromium.launch(headless=True)
    context = browser.new_context(ignore_https_errors=True)
    page = context.new_page()

    page.set_viewport_size({"width": 1440, "height": 900})
    page.goto('https://127.0.0.1:5110/nexifynewweb/', timeout=30000)
    page.wait_for_load_state("domcontentloaded")

    # Force all reveal animations to show
    page.evaluate("""
        () => {
            // Trigger all reveal elements
            document.querySelectorAll('.reveal').forEach(el => {
                el.classList.add('visible');
                el.style.opacity = '1';
                el.style.transform = 'none';
            });
            // Also check data-animate
            document.querySelectorAll('[data-animate]').forEach(el => {
                el.classList.add('animated', 'visible');
                el.style.opacity = '1';
                el.style.transform = 'none';
            });
        }
    """)
    page.wait_for_timeout(500)

    # Screenshot at different scroll positions
    for pos, name in [(0, 'top'), (900, 'mid1'), (1800, 'mid2'), (2700, 'mid3'), (3600, 'bottom')]:
        page.evaluate(f"window.scrollTo(0, {pos})")
        page.wait_for_timeout(300)
        page.screenshot(path=f'/tmp/nexify_scroll_{name}.png')

    # Also full page with forced visibility
    page.evaluate("window.scrollTo(0, 0)")
    page.wait_for_timeout(500)
    page.screenshot(path='/tmp/nexify_full_forced.png', full_page=True)

    print("Screenshots taken")
    browser.close()
EOF

